//watchdog('rule','rules_translate_node Z - user lang: ' . $lang . ' |  node lang: ' . $node_lang . ' | ' . $title);
$format_id =  'filtered_html';

$new_body = $new_body == 'error' ? '' : html_entity_decode($new_body);
$new_title = $new_title == 'error' ? '' : html_entity_decode($new_title);

$langs = language_list();

if ( !isset($langs[$node_lang])) {
	$object = new stdClass();
	$object->native = t('Undetermined');
	$object->name = t('Undetermined');
	$langs['und'] = $object;
}

//$bodytext = $new_body . '<br><br><i>' . t('This content was machine-translated from language <strong>@language</strong> (@langname).',array('@language' => $langs[$node_lang]->native, '@langname' =>  $langs[$node_lang]->name)) . '</i>';

//double save is necessary to deal with the title module inability to save value into language other than the $node->language
$source_key = ($node_lang === 'und') ? LANGUAGE_NONE : $node_lang;
$source_title_original = '';
if (isset($node->title_field[$source_key][0]['value'])) {
  $source_title_original = $node->title_field[$source_key][0]['value'];
}
elseif (isset($node->title_field[$node_lang][0]['value'])) {
  $source_title_original = $node->title_field[$node_lang][0]['value'];
}

$obj = entity_metadata_wrapper('node', $node);

$obj->language($lang)->body->value = $new_body;
$obj->language($lang)->body->format = $format_id;

$obj->language($lang)->title_field = $new_title;
if ($source_title_original !== '') {
  $obj->language($node_lang)->title_field = $source_title_original;
}
$obj->save();

$obj = entity_metadata_wrapper('node', $node);
$obj->language($lang)->title_field = $new_title;
if ($source_title_original !== '') {
  $obj->language($node_lang)->title_field = $source_title_original;
}

$obj->save();

$handler = entity_translation_get_handler('node', $node,TRUE);

$translation = array(
  'translate' => 0,
  'status' => 1,
  'language' => $lang,
  'source' => $node->language,
);

$handler->setTranslation($translation);
$handler->saveTranslations();

// Reload so field_attach_view() sees DB values (field cache can stay stale on $node).
entity_get_controller('node')->resetCache(array($node->nid));
$fresh = node_load($node->nid, NULL, TRUE);
if ($fresh) {
  foreach (array('body', 'title_field') as $_fn) {
    if (property_exists($fresh, $_fn)) {
      $node->{$_fn} = $fresh->{$_fn};
    }
  }
}

// Rules runs after field_attach_view(); $node->content exists only during that build.
// node_load() + dsm() will never show 'content' — that is normal. Prefer the router
// page node when the Rules variable is not the same object as the one being rendered.
$render = NULL;
if (isset($node->content) && is_array($node->content)) {
  $render = $node;
}
elseif (function_exists('menu_get_object')) {
  $page_node = menu_get_object('node', 1);
  if ($page_node && !empty($page_node->nid) && (int) $page_node->nid === (int) $node->nid && isset($page_node->content) && is_array($page_node->content)) {
    foreach (array('body', 'title_field') as $_fn) {
      if (property_exists($node, $_fn)) {
        $page_node->{$_fn} = $node->{$_fn};
      }
    }
    $render = $page_node;
  }
}

if ($render && isset($render->content) && is_array($render->content)) {
  $view_mode = 'full';
  if (!empty($render->content['#view_mode'])) {
    $view_mode = $render->content['#view_mode'];
  }
  foreach (array('body', 'title_field') as $field_name) {
    if (isset($render->content[$field_name])) {
      unset($render->content[$field_name]);
    }
  }
  $rebuilt = field_attach_view('node', $render, $view_mode, $lang);
  foreach (array('body', 'title_field') as $field_name) {
    if (!empty($rebuilt[$field_name])) {
      $render->content[$field_name] = $rebuilt[$field_name];
    }
  }
  if ($render !== $node) {
    if (!isset($node->content) || !is_array($node->content)) {
      $node->content = array();
    }
    foreach (array('body', 'title_field') as $field_name) {
      if (isset($render->content[$field_name])) {
        $node->content[$field_name] = $render->content[$field_name];
      }
    }
  }
}
